/**
 * Procedural Landmark Finder & Coordinate Math Utilities.
 * Enables fast spatial lookup of nearest natural landmarks (villages, forests, water bodies)
 * across infinite procedural worlds generated by WorldNoise.
 */

import { WorldNoise, type VillageInfo } from './worldNoise.ts';
import { hash2D } from './noise.ts';
import { RENDER_TILE_SIZE } from './worldGen.ts';

export { RENDER_TILE_SIZE };

export type LandmarkType = 'village' | 'forest' | 'water';

export interface LandmarkResult {
  readonly tileX: number;
  readonly tileY: number;
  readonly worldX: number;
  readonly worldY: number;
  readonly distance: number; // Euclidean distance in tiles
  readonly type: LandmarkType;
  readonly name: string;
  readonly villageName?: string;
}

export interface TileCoordinates {
  readonly tileX: number;
  readonly tileY: number;
  readonly tx: number;
  readonly ty: number;
}

export interface WorldCoordinates {
  readonly worldX: number;
  readonly worldY: number;
  readonly x: number;
  readonly y: number;
}

/**
 * Converts integer tile coordinates to world pixel coordinates.
 * @param tileX Tile column coordinate
 * @param tileY Tile row coordinate
 * @param tileSize Tile width/height in pixels (default: RENDER_TILE_SIZE = 64)
 * @param centered If true, returns the center point of the tile (+tileSize/2)
 */
export function tileToWorld(
  tileX: number,
  tileY: number,
  tileSize: number = RENDER_TILE_SIZE,
  centered: boolean = false
): WorldCoordinates {
  const offset = centered ? Math.floor(tileSize / 2) : 0;
  const worldX = tileX * tileSize + offset;
  const worldY = tileY * tileSize + offset;
  return {
    worldX,
    worldY,
    x: worldX,
    y: worldY,
  };
}

/**
 * Converts continuous world pixel coordinates to integer tile coordinates using Math.floor.
 * @param worldX World X position in pixels
 * @param worldY World Y position in pixels
 * @param tileSize Tile width/height in pixels (default: RENDER_TILE_SIZE = 64)
 */
export function worldToTile(
  worldX: number,
  worldY: number,
  tileSize: number = RENDER_TILE_SIZE
): TileCoordinates {
  const tileX = Math.floor(worldX / tileSize);
  const tileY = Math.floor(worldY / tileSize);
  return {
    tileX,
    tileY,
    tx: tileX,
    ty: tileY,
  };
}

/**
 * Checks whether a given tile coordinate is classified as forest biome or canopy/spread.
 */
export function isForestTile(worldNoise: WorldNoise, tx: number, ty: number): boolean {
  if (worldNoise.isWaterAt(tx, ty)) {
    return false;
  }
  const biome = worldNoise.getBiomeAt(tx, ty);
  if (biome === 'forest') {
    return true;
  }
  const forest = worldNoise.getForestAt(tx, ty);
  return forest.zone !== 'none' || forest.density >= worldNoise.config.forestThreshold;
}

/**
 * Finds the nearest procedural village plaza to the given starting tile coordinates.
 * Searches concentric Voronoi macro cells until the closest plaza center is guaranteed.
 * 
 * @param worldNoise The WorldNoise procedural sampler
 * @param originTileX Origin tile X coordinate
 * @param originTileY Origin tile Y coordinate
 * @param maxCellRadius Maximum number of macro Voronoi cell rings to search (default 12)
 */
export function findNearestVillage(
  worldNoise: WorldNoise,
  originTileX: number,
  originTileY: number,
  maxCellRadius: number = 12
): LandmarkResult | null {
  const cellSize = worldNoise.config.villageCellSize;
  const originCol = Math.floor(originTileX / cellSize);
  const originRow = Math.floor(originTileY / cellSize);

  let bestPlazaX = 0;
  let bestPlazaY = 0;
  let bestDistance = Infinity;
  let foundVillage: VillageInfo | null = null;

  for (let ring = 0; ring <= maxCellRadius; ring++) {
    for (let c = originCol - ring; c <= originCol + ring; c++) {
      for (let r = originRow - ring; r <= originRow + ring; r++) {
        // Only evaluate the perimeter of the current ring
        if (Math.max(Math.abs(c - originCol), Math.abs(r - originRow)) !== ring) {
          continue;
        }

        const spawnHash = hash2D(c, r, worldNoise.seeds.villageVoronoi + 101);
        if (spawnHash < worldNoise.config.villageRarity) {
          const plazaX = Math.floor(
            (c + hash2D(c, r, worldNoise.seeds.villageVoronoi)) * cellSize
          );
          const plazaY = Math.floor(
            (r + hash2D(c, r, (worldNoise.seeds.villageVoronoi ^ 0x9e3779b9) | 0)) * cellSize
          );

          const dist = Math.hypot(plazaX - originTileX, plazaY - originTileY);
          if (dist < bestDistance) {
            bestDistance = dist;
            bestPlazaX = plazaX;
            bestPlazaY = plazaY;
            foundVillage = worldNoise.getVillageAt(plazaX, plazaY);
          }
        }
      }
    }

    // Stop searching once even the closest point of the next ring cannot beat our current best
    if (foundVillage && (ring - 1) * cellSize > bestDistance) {
      break;
    }
  }

  if (foundVillage === null) {
    return null;
  }

  const worldPos = tileToWorld(bestPlazaX, bestPlazaY, RENDER_TILE_SIZE, true);
  const targetVillage = foundVillage as VillageInfo;
  const villageName = targetVillage.villageName ?? 'Settlement';

  return {
    tileX: bestPlazaX,
    tileY: bestPlazaY,
    worldX: worldPos.worldX,
    worldY: worldPos.worldY,
    distance: bestDistance,
    type: 'village',
    name: `${villageName} Plaza`,
    villageName,
  };
}

/**
 * Finds the nearest forest tile to the given starting tile coordinates using an outward spiral search.
 * 
 * @param worldNoise The WorldNoise procedural sampler
 * @param originTileX Origin tile X coordinate
 * @param originTileY Origin tile Y coordinate
 * @param maxRadiusTiles Maximum tile radius to search (default 150)
 */
export function findNearestForest(
  worldNoise: WorldNoise,
  originTileX: number,
  originTileY: number,
  maxRadiusTiles: number = 150
): LandmarkResult | null {
  // Check origin tile first
  if (isForestTile(worldNoise, originTileX, originTileY)) {
    const worldPos = tileToWorld(originTileX, originTileY, RENDER_TILE_SIZE, true);
    return {
      tileX: originTileX,
      tileY: originTileY,
      worldX: worldPos.worldX,
      worldY: worldPos.worldY,
      distance: 0,
      type: 'forest',
      name: 'Forest Woodlands',
    };
  }

  let bestX = 0;
  let bestY = 0;
  let bestDist = Infinity;
  let found = false;

  for (let r = 1; r <= maxRadiusTiles; r++) {
    for (let dx = -r; dx <= r; dx++) {
      // Top and bottom edges of ring
      const points = [
        [originTileX + dx, originTileY - r],
        [originTileX + dx, originTileY + r],
      ];
      for (const [x, y] of points) {
        if (isForestTile(worldNoise, x, y)) {
          const dist = Math.hypot(x - originTileX, y - originTileY);
          if (dist < bestDist) {
            bestDist = dist;
            bestX = x;
            bestY = y;
            found = true;
          }
        }
      }
    }

    for (let dy = -r + 1; dy < r; dy++) {
      // Left and right edges of ring
      const points = [
        [originTileX - r, originTileY + dy],
        [originTileX + r, originTileY + dy],
      ];
      for (const [x, y] of points) {
        if (isForestTile(worldNoise, x, y)) {
          const dist = Math.hypot(x - originTileX, y - originTileY);
          if (dist < bestDist) {
            bestDist = dist;
            bestX = x;
            bestY = y;
            found = true;
          }
        }
      }
    }

    if (found) {
      break;
    }
  }

  if (!found) {
    return null;
  }

  const worldPos = tileToWorld(bestX, bestY, RENDER_TILE_SIZE, true);
  return {
    tileX: bestX,
    tileY: bestY,
    worldX: worldPos.worldX,
    worldY: worldPos.worldY,
    distance: bestDist,
    type: 'forest',
    name: 'Forest Woodlands',
  };
}

/**
 * Finds the nearest natural water basin/lake tile to the given starting tile coordinates.
 * 
 * @param worldNoise The WorldNoise procedural sampler
 * @param originTileX Origin tile X coordinate
 * @param originTileY Origin tile Y coordinate
 * @param maxRadiusTiles Maximum tile radius to search (default 200)
 */
export function findNearestWater(
  worldNoise: WorldNoise,
  originTileX: number,
  originTileY: number,
  maxRadiusTiles: number = 200
): LandmarkResult | null {
  if (worldNoise.isWaterAt(originTileX, originTileY)) {
    const worldPos = tileToWorld(originTileX, originTileY, RENDER_TILE_SIZE, true);
    return {
      tileX: originTileX,
      tileY: originTileY,
      worldX: worldPos.worldX,
      worldY: worldPos.worldY,
      distance: 0,
      type: 'water',
      name: 'Water Basin',
    };
  }

  let bestX = 0;
  let bestY = 0;
  let bestDist = Infinity;
  let found = false;

  for (let r = 1; r <= maxRadiusTiles; r++) {
    for (let dx = -r; dx <= r; dx++) {
      const points = [
        [originTileX + dx, originTileY - r],
        [originTileX + dx, originTileY + r],
      ];
      for (const [x, y] of points) {
        if (worldNoise.isWaterAt(x, y)) {
          const dist = Math.hypot(x - originTileX, y - originTileY);
          if (dist < bestDist) {
            bestDist = dist;
            bestX = x;
            bestY = y;
            found = true;
          }
        }
      }
    }

    for (let dy = -r + 1; dy < r; dy++) {
      const points = [
        [originTileX - r, originTileY + dy],
        [originTileX + r, originTileY + dy],
      ];
      for (const [x, y] of points) {
        if (worldNoise.isWaterAt(x, y)) {
          const dist = Math.hypot(x - originTileX, y - originTileY);
          if (dist < bestDist) {
            bestDist = dist;
            bestX = x;
            bestY = y;
            found = true;
          }
        }
      }
    }

    if (found) {
      break;
    }
  }

  if (!found) {
    return null;
  }

  const worldPos = tileToWorld(bestX, bestY, RENDER_TILE_SIZE, true);
  return {
    tileX: bestX,
    tileY: bestY,
    worldX: worldPos.worldX,
    worldY: worldPos.worldY,
    distance: bestDist,
    type: 'water',
    name: 'Water Basin',
  };
}
